const PAL = {
  C: 0x4b5058, H: 0x7cc0e8, O: 0xb23225, OH_H: 0x8f231a, G: 0x3fbf5c,
  BOND: 0xc9ced4, PLANE: 0xb9dff5, PLANE_EDGE: 0x7fb8dc, HL: 0xffd24d
};

/* ── lights ─────────────────────────────────────────────────────────────── */
