  return m;
}

/* ── 3D molecule: meso tartaric acid ────────────────────────────────────── */
const HALF = {
  C:   [0.00, 0.80,  0.00],
  O1:  [-0.90, 1.40, 0.15],
  HO:  [-1.50, 1.05, 0.30],
  H:   [0.55, 0.45,  0.85],
  CB:  [0.95, 1.40, -0.10],
  OB1: [1.90, 1.15,  0.10],
  OB2: [0.95, 2.40, -0.30],
  HB:  [2.45, 1.60,  0.30]
