}
panelLabel('C', 0, 0.55, { fontSize: '16px', color: '#111' });
panelLabel('C', 0, -0.55, { fontSize: '16px', color: '#111' });
panelLabel('H', 0, 1.30, { fontSize: '15px', color: '#1f8fc2' }, 'H');
panelLabel('H', 0, -1.30, { fontSize: '15px', color: '#1f8fc2' }, 'H');
panelLabel('HO', -1.02, 0.93, { fontSize: '15px', color: '#d4197f', bold: true }, 'OH');
panelLabel('HO', -1.02, -0.93, { fontSize: '15px', color: '#d4197f', bold: true }, 'OH');
panelLabel('CO<sub>2</sub>H', 1.32, 0.93, { fontSize: '15px', color: '#127a4a', bold: true }, 'CO2H');
panelLabel('CO<sub>2</sub>H', 1.32, -0.93, { fontSize: '15px', color: '#127a4a', bold: true }, 'CO2H');
panelLabel('Symmetry plane', 2.05, 0.00, { fontSize: '15px', color: '#111' });

const flashLabel = addLabel('superimposable &#10003;', new THREE.Vector3(0.35, -0.05, 1.45),
  { fontSize: '14px', color: '#8a6500', bold: true, background: 'rgba(255,210,77,0.55)' });
flashLabel.div.style.opacity = '0';

/* ── representation modes ───────────────────────────────────────────────── */
let mode = 'overlay';
const btnStruct = document.getElementById('mStruct');
const btnModel = document.getElementById('mModel');
const btnOverlay = document.getElementById('mOverlay');

function setPanelOpacity(v) {
  panelMats.forEach(m => { m.opacity = v; m.transparent = true; });
  panelLabels.forEach(l => { l.entry.div.style.opacity = String(v); });
}
