    }
  } else if (ghostState === 'flash') {
    flashT += dt;
    if (flashT > 1.3) {
      setGlow(bottomHalf, false);
      highlighted.forEach(g => setGlow(g, true));
      flashLabel.div.style.opacity = '0';
      disposeGhost();
      ghostState = 'idle';
    }
  }
}
tick();
// @FIGURE_CODE_END

