function atom(pos, r, color, parent) {
  const m = new THREE.Mesh(
    new THREE.SphereGeometry(r, 32, 24),
    new THREE.MeshPhongMaterial({ color, specular: 0xffffff, shininess: 85, emissive: 0x000000 })
  );
  m.position.copy(pos);
  parent.add(m);
  return m;
}
function bond(a, b, parent, r) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const m = new THREE.Mesh(
    new THREE.CylinderGeometry(r || 0.09, r || 0.09, len, 18),
    new THREE.MeshPhongMaterial({ color: PAL.BOND, specular: 0xffffff, shininess: 55, emissive: 0x000000 })
  );
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  parent.add(m);
  return m;
}

/* ── 3D molecule: meso tartaric acid ────────────────────────────────────── */
const HALF = {
  C:   [0.00, 0.80,  0.00],
  O1:  [-0.90, 1.40, 0.15],
  HO:  [-1.50, 1.05, 0.30],
  H:   [0.58, 0.42,  0.92],
  CB:  [0.95, 1.40, -0.10],
  OB1: [1.90, 1.15,  0.10],
  OB2: [0.95, 2.40, -0.30],
  HB:  [2.45, 1.60,  0.30]
