const modelGroup = new THREE.Group();
const allSubs = [];

function buildHalf(sign) {
  const half = sign > 0 ? 'top' : 'bottom';
  const g = new THREE.Group();
  const P = a => new THREE.Vector3(a[0], a[1] * sign, a[2]);
  const c = P(HALF.C);
  atom(c, 0.38, PAL.C, g);

  // hydroxyl
  const oh = new THREE.Group();
  oh.userData = { half, group: 'OH' };
  const o = P(HALF.O1), hh = P(HALF.HO);
  bond(c, o, oh); bond(o, hh, oh, 0.07);
  atom(o, 0.34, PAL.O, oh); atom(hh, 0.20, PAL.OH_H, oh);
  g.add(oh);

  // stereocenter hydrogen (small pale-blue sphere toward the viewer)
  const hg = new THREE.Group();
  hg.userData = { half, group: 'H' };
  const h = P(HALF.H);
  bond(c, h, hg, 0.07); atom(h, 0.22, PAL.H, hg);
  g.add(hg);

  // carboxyl group
  const cg = new THREE.Group();
  cg.userData = { half, group: 'CO2H' };
  const cb = P(HALF.CB), ob1 = P(HALF.OB1), ob2 = P(HALF.OB2), hb = P(HALF.HB);
  bond(c, cb, cg); bond(cb, ob1, cg); bond(cb, ob2, cg); bond(ob1, hb, cg, 0.07);
  atom(cb, 0.34, PAL.G, cg); atom(ob1, 0.34, PAL.G, cg);
  atom(ob2, 0.34, PAL.G, cg); atom(hb, 0.20, PAL.G, cg);
  g.add(cg);

  allSubs.push(oh, hg, cg);
  return g;
}

