<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
  3D MODEL (right) — true tetrahedral / sp2 frames, built from direction vectors
   stereocenter C (x2)      → SphereGeometry(0.38)  MeshPhong #63686f (medium gray)
   stereocenter H (x2)      → SphereGeometry(0.22)  MeshPhong #7cc0e8, aimed at viewer
   hydroxyl O (x2)          → SphereGeometry(0.34)  MeshPhong #b23225  (up-left)
   hydroxyl H (x2)          → SphereGeometry(0.20)  MeshPhong #8f231a  (bent, down-left)
   carboxyl C + 2 O (x2)    → SphereGeometry(0.34)  MeshPhong #43b055  sp2, 120° spread
   acid H (x2)              → SphereGeometry(0.20)  MeshPhong #43b055
   bonds                    → CylinderGeometry(r .10 / .075) MeshPhong #c9ced4
   symmetry plane           → PlaneGeometry(3.0,2.0) rotX(-90) MeshBasic #b9dff5 45%
                              + LineLoop edge #7fb8dc  (y = 0, ⟂ to C–C), shifted right
  2D PANEL (billboarded flat drawing, screen-left)
   plain bonds              → thick PlaneGeometry quads, black (w 0.050)
   dashed C–H bonds         → stacks of short black quads (w 0.055)
   bold wedge to HO         → ShapeGeometry filled triangle, black (half-width 0.15)
   edge-on symmetry plane   → ShapeGeometry parallelogram #b9dff5
   lettering                → addLabel HTML (C, H, HO, CO2H, Symmetry plane)
─────────────────────────────────────────────────────────────────────────── */

const DEG = THREE.MathUtils.degToRad;
const V = (x, y, z) => new THREE.Vector3(x, y, z);

const PAL = {
  C: 0x63686f, H: 0x7cc0e8, O: 0xb23225, OH_H: 0x8f231a, G: 0x43b055,
  BOND: 0xc9ced4, PLANE: 0xb9dff5, PLANE_EDGE: 0x7fb8dc, HL: 0xffd24d
};

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.74));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.72);
keyLight.position.set(4, 6, 7); scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.28);
fillLight.position.set(-5, -3, 4); scene.add(fillLight);

/* ── helpers ────────────────────────────────────────────────────────────── */
function atom(pos, r, color, parent) {
  const m = new THREE.Mesh(
    new THREE.SphereGeometry(r, 32, 24),
    new THREE.MeshPhongMaterial({ color, specular: 0xffffff, shininess: 90, emissive: 0x000000 })
  );
  m.position.copy(pos);
  parent.add(m);
  return m;
}
function bond(a, b, parent, r) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const m = new THREE.Mesh(
    new THREE.CylinderGeometry(r || 0.10, r || 0.10, len, 18),
    new THREE.MeshPhongMaterial({ color: PAL.BOND, specular: 0xffffff, shininess: 60, emissive: 0x000000 })
  );
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(V(0, 1, 0), dir.clone().normalize());
  parent.add(m);
  return m;
}

/* ── true tetrahedral / sp2 coordinates for the upper half ──────────────── */
function halfGeometry() {
  const C = V(0, 0.8, 0);
  const axis = V(0, -1, 0);              // bond toward the other stereocenter
  const e1 = V(1, 0, 0), e2 = V(0, 0, 1);
  const ct = Math.cos(DEG(109.47)), st = Math.sin(DEG(109.47));
  const dirAt = p => axis.clone().multiplyScalar(ct)
    .addScaledVector(e1, st * Math.cos(DEG(p)))
    .addScaledVector(e2, st * Math.sin(DEG(p))).normalize();

  // phi chosen so H points straight at the viewer, OH to screen-left, CO2H to screen-right
  const dH = dirAt(45), dO = dirAt(165), dCB = dirAt(-75);

  const H = C.clone().addScaledVector(dH, 1.04);
  const O = C.clone().addScaledVector(dO, 1.18);

  // bent hydroxyl (≈109° at oxygen), swinging down-left
  const bO = new THREE.Vector3().crossVectors(dO, V(0, 0, 1)).normalize();
  const dOH = dO.clone().multiplyScalar(Math.cos(DEG(71)))
    .addScaledVector(bO, -Math.sin(DEG(71))).normalize();
  const HO = O.clone().addScaledVector(dOH, 0.94);

  // planar sp2 carboxyl, its plane turned face-on to the default view so it opens up
  const CB = C.clone().addScaledVector(dCB, 1.40);
  const view = V(1, 1, 1).normalize();
  const p = new THREE.Vector3().crossVectors(dCB, view).normalize();
  const s60 = Math.sin(DEG(60));
  const d1 = dCB.clone().multiplyScalar(0.5).addScaledVector(p, s60).normalize();
  const d2 = dCB.clone().multiplyScalar(0.5).addScaledVector(p, -s60).normalize();
  const OB1 = CB.clone().addScaledVector(d1, 1.18);
  const OB2 = CB.clone().addScaledVector(d2, 1.18);
  const q = dCB.clone().multiplyScalar(-s60).addScaledVector(p, 0.5).normalize();
  const dAH = d1.clone().multiplyScalar(Math.cos(DEG(70)))
    .addScaledVector(q, -Math.sin(DEG(70))).normalize();
  const HB = OB1.clone().addScaledVector(dAH, 0.94);

  return { C, H, O, HO, CB, OB1, OB2, HB };
}
const G0 = halfGeometry();

/* ── 3D molecule: meso tartaric acid ────────────────────────────────────── */
const modelGroup = new THREE.Group();
const allSubs = [];

function buildHalf(sign) {
  const half = sign > 0 ? 'top' : 'bottom';
  const g = new THREE.Group();
  const M = v => V(v.x, v.y * sign, v.z);      // mirror through y = 0
  const c = M(G0.C);
  atom(c, 0.38, PAL.C, g);

  // hydroxyl
  const oh = new THREE.Group();
  oh.userData = { half, group: 'OH' };
  const o = M(G0.O), hh = M(G0.HO);
  bond(c, o, oh, 0.10); bond(o, hh, oh, 0.075);
  atom(o, 0.34, PAL.O, oh); atom(hh, 0.20, PAL.OH_H, oh);
  g.add(oh);

  // stereocenter hydrogen — pale-blue sphere pointing at the viewer
  const hg = new THREE.Group();
  hg.userData = { half, group: 'H' };
  const h = M(G0.H);
  bond(c, h, hg, 0.075); atom(h, 0.22, PAL.H, hg);
  g.add(hg);

  // carboxyl branch
  const cg = new THREE.Group();
  cg.userData = { half, group: 'CO2H' };
  const cb = M(G0.CB), ob1 = M(G0.OB1), ob2 = M(G0.OB2), hb = M(G0.HB);
  bond(c, cb, cg, 0.10); bond(cb, ob1, cg, 0.10); bond(cb, ob2, cg, 0.10); bond(ob1, hb, cg, 0.075);
  atom(cb, 0.34, PAL.G, cg); atom(ob1, 0.34, PAL.G, cg);
  atom(ob2, 0.34, PAL.G, cg); atom(hb, 0.20, PAL.G, cg);
  g.add(cg);

  allSubs.push(oh, hg, cg);
  return g;
}

const topHalf = buildHalf(1);
const bottomHalf = buildHalf(-1);
modelGroup.add(topHalf, bottomHalf);
bond(V(0, 0.8, 0), V(0, -0.8, 0), modelGroup, 0.11);

/* symmetry plane of the model — horizontal, ⟂ to the C–C bond, compact */
const PW = 3.0, PD = 2.0, PCX = 0.5;
const planeMat = new THREE.MeshBasicMaterial({
  color: PAL.PLANE, transparent: true, opacity: 0.5,
  depthWrite: false, side: THREE.DoubleSide
});
const plane3D = new THREE.Mesh(new THREE.PlaneGeometry(PW, PD), planeMat);
plane3D.rotation.x = -Math.PI / 2;
plane3D.position.set(PCX, 0, 0);
plane3D.renderOrder = 10;
modelGroup.add(plane3D);
const hw = PW / 2, hd = PD / 2;
const planeEdge = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    V(-hw, 0, -hd), V(hw, 0, -hd), V(hw, 0, hd), V(-hw, 0, hd), V(-hw, 0, -hd)
  ]),
  new THREE.LineBasicMaterial({ color: PAL.PLANE_EDGE, transparent: true, opacity: 0.85, depthWrite: false })
);
planeEdge.position.set(PCX, 0, 0);
planeEdge.renderOrder = 11;
modelGroup.add(planeEdge);

/* ── 2D structural drawing (billboarded flat panel, screen-left) ────────── */
const PANEL_DIST = 4.6;
const panelGroup = new THREE.Group();
const panelMats = [];

function pmat(color) {
  const m = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide, transparent: true, opacity: 1 });
  panelMats.push(m);
  return m;
}
function seg2d(a, b, w, color, z) {
  const dx = b[0] - a[0], dy = b[1] - a[1], len = Math.hypot(dx, dy);
  const m = new THREE.Mesh(new THREE.PlaneGeometry(len, w), pmat(color));
  m.position.set((a[0] + b[0]) / 2, (a[1] + b[1]) / 2, z || 0);
  m.rotation.z = Math.atan2(dy, dx);
  panelGroup.add(m);
  return m;
}
function dashed2d(a, b, n, w, color) {
  for (let i = 0; i < n; i++) {
    const t0 = i / n, t1 = t0 + 0.55 / n;
    seg2d([a[0] + (b[0] - a[0]) * t0, a[1] + (b[1] - a[1]) * t0],
          [a[0] + (b[0] - a[0]) * t1, a[1] + (b[1] - a[1]) * t1], w, color, 0.002);
  }
}
function wedge2d(apex, tip, halfw, color) {
  const dx = tip[0] - apex[0], dy = tip[1] - apex[1], len = Math.hypot(dx, dy);
  const px = -dy / len * halfw, py = dx / len * halfw;
  const s = new THREE.Shape();
  s.moveTo(apex[0], apex[1]);
  s.lineTo(tip[0] + px, tip[1] + py);
  s.lineTo(tip[0] - px, tip[1] - py);
  s.closePath();
  const m = new THREE.Mesh(new THREE.ShapeGeometry(s), pmat(color));
  m.position.z = 0.003;
  panelGroup.add(m);
  return m;
}

for (const s of [1, -1]) {
  dashed2d([0, 0.76 * s], [0, 1.14 * s], 5, 0.055, 0x111111);          // C–H dashed, heavier
  wedge2d([-0.13, 0.60 * s], [-0.72, 0.90 * s], 0.150, 0x111111);      // bold wedge to HO
  seg2d([0.15, 0.62 * s], [0.82, 0.92 * s], 0.050, 0x111111);          // plain bond to CO2H
}
seg2d([0, 0.38], [0, -0.38], 0.050, 0x111111);                         // C–C bond

// edge-on symmetry plane of the drawing
const par = new THREE.Shape();
par.moveTo(-1.30, -0.10); par.lineTo(0.46, -0.10);
par.lineTo(0.86, 0.10); par.lineTo(-0.90, 0.10); par.closePath();
const parMesh = new THREE.Mesh(new THREE.ShapeGeometry(par), pmat(PAL.PLANE));
parMesh.position.z = -0.004;
panelGroup.add(parMesh);

scene.add(panelGroup, modelGroup);

/* ── camera / framing ───────────────────────────────────────────────────── */
controls.minPolarAngle = Math.PI * 30 / 180;
controls.maxPolarAngle = Math.PI * 150 / 180;
document.getElementById('btnReset').style.display = '';

const panelLabels = [];
const _camRight = new THREE.Vector3();
function updatePanel() {
  _camRight.set(1, 0, 0).applyQuaternion(camera.quaternion);
  _camRight.y = 0;
  if (_camRight.lengthSq() < 1e-6) _camRight.set(1, 0, 0);
  _camRight.normalize();
  panelGroup.position.copy(_camRight).multiplyScalar(-PANEL_DIST);
  panelGroup.quaternion.copy(camera.quaternion);
  panelGroup.updateMatrixWorld(true);
  for (const l of panelLabels) l.entry.pos.copy(l.local).applyMatrix4(panelGroup.matrixWorld);
}

let _firstFit = true;
function refit() {
  const useDefault = _firstFit;
  for (let i = 0; i < 3; i++) {
    updatePanel();
    if (useDefault) {
      setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.65 });
    } else {
      const off = camera.position.clone().sub(controls.target);
      const r = off.length() || 1;
      setCameraView({
        projection: 'orthographic',
        azimuthDeg: THREE.MathUtils.radToDeg(Math.atan2(off.z, off.x)),
        elevationDeg: THREE.MathUtils.radToDeg(Math.asin(THREE.MathUtils.clamp(off.y / r, -1, 1))),
        heightFraction: 0.65
      });
    }
  }
  _firstFit = false;
}

/* ── labels ─────────────────────────────────────────────────────────────── */
function panelLabel(html, lx, ly, opts, tag) {
  const e = addLabel(html, V(lx, ly, 0.01), opts);
  panelLabels.push({ entry: e, local: V(lx, ly, 0.01), group: tag || null });
  return e;
}
panelLabel('C', 0, 0.55, { fontSize: '17px', color: '#111' });
panelLabel('C', 0, -0.55, { fontSize: '17px', color: '#111' });
panelLabel('H', 0, 1.32, { fontSize: '15px', color: '#1f8fc2' }, 'H');
panelLabel('H', 0, -1.32, { fontSize: '15px', color: '#1f8fc2' }, 'H');
panelLabel('HO', -1.10, 0.98, { fontSize: '16px', color: '#d4197f', bold: true }, 'OH');
panelLabel('HO', -1.10, -0.98, { fontSize: '16px', color: '#d4197f', bold: true }, 'OH');
panelLabel('CO<sub>2</sub>H', 1.40, 0.98, { fontSize: '16px', color: '#127a4a', bold: true }, 'CO2H');
panelLabel('CO<sub>2</sub>H', 1.40, -0.98, { fontSize: '16px', color: '#127a4a', bold: true }, 'CO2H');
panelLabel('Symmetry plane', 1.95, 0.00, { fontSize: '16px', color: '#111' });

refit();

const flashLabel = addLabel('superimposable &#10003;', V(1.25, 0.06, -0.2),
  { fontSize: '14px', color: '#7a5a00', bold: true, background: 'rgba(255,210,77,0.75)' });
flashLabel.div.style.opacity = '0';

/* ── representation modes ───────────────────────────────────────────────── */
let mode = 'overlay';
const btnStruct = document.getElementById('mStruct');
const btnModel = document.getElementById('mModel');
const btnOverlay = document.getElementById('mOverlay');

function setPanelVisible(on, opacity) {
  panelMats.forEach(m => { m.opacity = opacity; m.transparent = opacity < 1; });
  panelLabels.forEach(l => { l.entry.div.style.opacity = on ? String(opacity) : '0'; });
}
function setMode(m) {
  mode = m;
  [btnStruct, btnModel, btnOverlay].forEach(b => b.classList.remove('active'));
  if (m === 'structure') {
    if (!panelGroup.parent) scene.add(panelGroup);
    if (modelGroup.parent) scene.remove(modelGroup);
    setPanelVisible(true, 1);
    btnStruct.classList.add('active');
  } else if (m === 'model') {
    if (panelGroup.parent) scene.remove(panelGroup);
    if (!modelGroup.parent) scene.add(modelGroup);
    setPanelVisible(false, 0);
    btnModel.classList.add('active');
  } else {
    if (!panelGroup.parent) scene.add(panelGroup);
    if (!modelGroup.parent) scene.add(modelGroup);
    setPanelVisible(true, 1);
    btnOverlay.classList.add('active');
  }
  refit();
}
btnStruct.onclick = () => setMode('structure');
btnModel.onclick = () => setMode('model');
btnOverlay.onclick = () => setMode('overlay');

/* ── pick a group → its mirror partner lights up ────────────────────────── */
const pickInfo = document.getElementById('pickInfo');
let highlighted = [];
function setGlow(g, on) {
  g.traverse(o => {
    if (o.isMesh && o.material && o.material.emissive) {
      o.material.emissive.setHex(on ? PAL.HL : 0x000000);
    }
  });
}
function clearHighlight() {
  highlighted.forEach(g => setGlow(g, false));
  highlighted = [];
  panelLabels.forEach(l => { l.entry.div.style.background = 'none'; l.entry.div.style.padding = '0'; });
  pickInfo.textContent = '';
}
const GROUP_TEXT = {
  OH: 'HO\u2014 on the top center and HO\u2014 on the bottom center are reflections through the plane.',
  H: 'The two stereocenter H atoms point to opposite sides \u2014 exact mirror images.',
  CO2H: 'The two \u2014CO\u2082H branches are mirror copies; their handedness cancels.'
};
function highlightPair(tag) {
  clearHighlight();
  allSubs.filter(s => s.userData.group === tag).forEach(s => { setGlow(s, true); highlighted.push(s); });
  panelLabels.filter(l => l.group === tag).forEach(l => {
    l.entry.div.style.background = 'rgba(255,210,77,0.6)';
    l.entry.div.style.padding = '1px 4px';
    l.entry.div.style.borderRadius = '3px';
  });
  pickInfo.innerHTML = '<b>' + (tag === 'CO2H' ? 'CO<sub>2</sub>H' : tag) + ' pair matched.</b> ' + GROUP_TEXT[tag];
}

const NAMES = { OH: 'Hydroxyl (\u2013OH)', H: 'Stereocenter hydrogen', CO2H: 'Carboxyl (\u2013CO\u2082H)' };
allSubs.forEach(s => {
  const tag = s.userData.group, half = s.userData.half;
  registerInteractive(s, {
    title: NAMES[tag] + ' \u2014 ' + half + ' stereocenter',
    body: GROUP_TEXT[tag] + ' Because every substituent on C2 has a mirror partner on C3, the two chirality centers have opposite configurations and the molecule is meso (achiral).',
    tooltip: 'Click: match ' + (tag === 'CO2H' ? 'CO\u2082H' : tag) + ' across the plane',
    onClick: () => highlightPair(tag)
  });
});
registerInteractive(plane3D, {
  title: 'Internal symmetry plane',
  body: 'This mirror plane sits perpendicular to the central C\u2013C bond. Reflecting the top half through it reproduces the bottom half exactly, so the molecule is superimposable on its own mirror image.',
  tooltip: 'Internal mirror plane'
});

const _rc = new THREE.Raycaster(), _pt = new THREE.Vector2();
canvas.addEventListener('click', (ev) => {
  const r = canvas.getBoundingClientRect();
  _pt.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  _pt.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  _rc.setFromCamera(_pt, camera);
  if (_rc.intersectObjects(allSubs, true).length === 0) clearHighlight();
});

/* ── fold / reflect through the plane ───────────────────────────────────── */
const foldSlider = document.getElementById('fold');
let ghost = null, animT = 0, animRun = false, flashT = 0, flashing = false;

function makeGhost() {
  if (ghost) return;
  ghost = topHalf.clone(true);
  ghost.traverse(o => {
    if (o.isMesh) {
      o.material = new THREE.MeshPhongMaterial({
        color: 0x2fd0e0, specular: 0xffffff, shininess: 90,
        transparent: true, opacity: 0.55, depthWrite: false
      });
    }
  });
  modelGroup.add(ghost);
}
function disposeGhost() {
  if (!ghost) return;
  ghost.traverse(o => { if (o.isMesh) { o.geometry.dispose(); o.material.dispose(); } });
  modelGroup.remove(ghost);
  ghost = null;
}
function setFold(t) {
  t = Math.max(0, Math.min(1, t));
  if (t <= 0.002) {
    disposeGhost();
    if (flashing) { setGlow(bottomHalf, false); highlighted.forEach(g => setGlow(g, true)); flashing = false; }
    flashLabel.div.style.opacity = '0';
    return;
  }
  if (mode === 'structure') setMode('model');
  makeGhost();
  let s = 1 - 2 * t;
  if (Math.abs(s) < 0.005) s = 0.005;
  ghost.scale.y = s;
  const done = t > 0.985;
  if (done && !flashing) { flashing = true; setGlow(bottomHalf, true); flashLabel.div.style.opacity = '1'; }
  if (!done && flashing) {
    flashing = false; setGlow(bottomHalf, false);
    highlighted.forEach(g => setGlow(g, true));
    flashLabel.div.style.opacity = '0';
  }
}
foldSlider.addEventListener('input', () => { animRun = false; setFold(foldSlider.value / 100); });

function startReflect() {
  if (mode === 'structure') setMode('model');
  animT = 0; animRun = true; flashT = 0;
  setFold(0);
}
document.getElementById('btnReflect').onclick = startReflect;

/* ── guided tour ────────────────────────────────────────────────────────── */
const steps = [
  { title: 'The flat drawing', mode: 'structure',
    narration: 'Two stereocenters stacked vertically: each carries HO on a bold wedge to the left and CO\u2082H to the right, but the dashed H atoms point in opposite directions. A pale blue plane slices between them.' },
  { title: 'Same molecule in 3D', mode: 'model',
    narration: 'The ball-and-stick model shows the same arrangement on proper tetrahedral carbons: gray C, a small blue H aimed at you, a red OH and a green CO\u2082H on each center, cut by the same horizontal plane.' },
  { title: 'Check group against group', mode: 'overlay', action: () => highlightPair('OH'),
    narration: 'Click HO, H or CO\u2082H on the upper center; its mirror partner below lights up. Every substituent is matched across the plane.' },
  { title: 'Fold it over', mode: 'model', action: () => startReflect(),
    narration: 'Reflecting the top half through the plane superimposes it on the bottom half \u2014 the internal mirror makes this meso compound achiral.' }
];
let stepIdx = 0;
const stepTitle = document.getElementById('stepTitle');
const stepNarr = document.getElementById('stepNarr');
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  clearHighlight();
  animRun = false; foldSlider.value = 0; setFold(0);
  setMode(s.mode);
  stepTitle.textContent = (stepIdx + 1) + '. ' + s.title;
  stepNarr.textContent = s.narration;
  if (s.action) s.action();
}
document.getElementById('stepPrev').onclick = () => goToStep(stepIdx - 1);
document.getElementById('stepNext').onclick = () => goToStep(stepIdx + 1);
stepTitle.textContent = 'Meso tartaric acid';
stepNarr.textContent = 'Both depictions of the same molecule, cut by one internal mirror plane. Use Next to walk through the argument.';

setMode('overlay');

/* ── per-frame: keep panel screen-left & facing camera, drive the fold ──── */
let _prev = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _prev) / 1000);
  _prev = now;

  updatePanel();

  if (animRun) {
    animT += dt / 1.5;
    const t = Math.min(1, animT), e = t * t * (3 - 2 * t);
    foldSlider.value = Math.round(e * 100);
    setFold(e);
    if (t >= 1) { animRun = false; flashT = 0; }
  } else if (flashing) {
    flashT += dt;
    if (flashT > 1.6) { foldSlider.value = 0; setFold(0); }
  }
}
tick();
